input.command:
cd /c/Users/Client/.claude/projects/d--2026---Tuan-danang-vite && cat > "$TEMP/tail.mjs" <<'EOF'
import fs from 'fs';
for (const f of process.argv.slice(2)) {
  const lines = fs.readFileSync(f,'utf8').trim().split('\n');
  let first=null, users=[], asst=[], cwd=null, branch=null, lastTs=null, tools=[];
  for (const l of lines) { let o; try{o=JSON.parse(l)}catch{continue}
    if (o.cwd) cwd=o.cwd; if (o.gitBranch) branch=o.gitBranch; if (o.timestamp) lastTs=o.timestamp;
    if (o.isSidechain) continue;
    const c=o.message?.content;
    if (o.type==='user') { const t= typeof c==='string'?c:(Array.isArray(c)?c.filter(x=>x.type==='text').map(x=>x.text).join(' '):''); if (t && !t.startsWith('<')) { if(!first) first=t; users.push([o.timestamp,t]); } }
    if (o.type==='assistant' && Array.isArray(c)) { for (const x of c){ if (x.type==='text'&&x.text.trim()) asst.push([o.timestamp,x.text]); if (x.type==='tool_use') tools.push([o.timestamp,x.name, JSON.stringify(x.input).slice(0,160)]); } }
  }
  console.log('\n=====',f,'| cwd',cwd,'| branch',branch,'| last',lastTs);
  console.log('FIRST:',first?.slice(0,300));
  console.log('LAST USERS:'); users.slice(-3).forEach(u=>console.log(' ',u[0],u[1].slice(0,300).replace(/\n/g,' ')));
  console.log('LAST ASSISTANT:'); asst.slice(-2).forEach(u=>console.log(' ',u[0],u[1].slice(0,1500)));
  console.log('LAST TOOLS:'); tools.slice(-3).forEach(u=>console.log(' ',u.join(' ')));
}
EOF
