import fs from 'node:fs'; import path from 'node:path';
const src = process.argv[2], out = process.argv[3];
fs.rmSync(out, { recursive: true, force: true });
const SHIM = `<script>/* Bản demo: máy chủ không phục vụ .glb / .bin nên mô hình được đóng gói dạng base64 (.b64.txt) và giải mã tại đây */
(function(){var F=window.fetch.bind(window);window.fetch=function(i,o){var u=typeof i==='string'?i:(i&&i.url)||'';if(/\\.(glb|bin)(\\?|$)/.test(u)){return F(u.replace(/\\?.*$/,'')+'.b64.txt').then(function(r){if(!r.ok)return r;return r.text().then(function(t){var b=atob(t),a=new Uint8Array(b.length);for(var k=0;k<b.length;k++)a[k]=b.charCodeAt(k);return new Response(a,{status:200,headers:{'content-type':'application/octet-stream','content-length':String(a.length)}});});});}return F(i,o);};})();
</script>`;
const files = [];
const slash = (p) => p.split(path.sep).join('/');
const walk = (d) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else files.push(slash(path.relative(src, p))); } };
walk(src);
const list = [];
for (const f of files) {
  if (f.startsWith('voice/') && f !== 'voice/manifest.json' && f !== 'voice/vi/stops-0.mp3') continue;   // chỉ giữ một clip thuyết minh như bản demo trước
  let as = f, data = fs.readFileSync(path.join(src, f));
  if (/\.(glb|bin)$/.test(f)) { as = f + '.b64.txt'; data = Buffer.from(data.toString('base64')); }
  if (f === 'index.html') { const h = data.toString('utf8'); if (!h.includes('<meta charset="utf-8">')) throw new Error('index.html đổi'); data = Buffer.from(h.replace('<meta charset="utf-8">', '<meta charset="utf-8">\n' + SHIM)); }
  const o = path.join(out, as); fs.mkdirSync(path.dirname(o), { recursive: true }); fs.writeFileSync(o, data);
  list.push({ as, path: slash(path.resolve(o)), kb: Math.round(data.length / 1024) });
}
fs.writeFileSync(path.join(out, '..', 'demo-files.json'), JSON.stringify(list.map(({ as, path }) => ({ as, path }))));
console.log(list.map((x) => `${x.kb} kB ${x.as}`).join('\n'), '\nTổng', Math.round(list.reduce((s, x) => s + x.kb, 0) / 1024), 'MB,', list.length, 'tệp');

